// Runnable demo: load balancing + rebalance on join and failure.
package com.bank.rebalance.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class RebalanceDemo {
    private static final Logger log = Logger.getLogger(RebalanceDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ProcessorGroup group = new ProcessorGroup("txn-processors", 6); // 6 partitions

        // Start with 2 instances — balanced 3 + 3
        group.join("proc-1");
        group.join("proc-2");
        group.showLoad();

        // Scale up: a 3rd instance joins -> rebalance to 2 + 2 + 2
        log.info(() -> "Scaling up: proc-3 joins");
        group.join("proc-3");
        group.showLoad();

        // Failure: proc-2 crashes (missed heartbeats) -> survivors take over
        log.warning(() -> "proc-2 missed heartbeats — treated as failed");
        group.fail("proc-2");
        group.showLoad();
    }
}

