class PartitionLog {
    private final int id;
    private long committedOffset = 0;
    PartitionLog(int id) { this.id = id; }
    int getId() { return id; }
    long getCommittedOffset() { return committedOffset; }
    void commit(long offset) { this.committedOffset = offset; }
}

// ─── Would be in Rebalancer.java ───
class Rebalancer {
    private static final Logger log = Logger.getLogger(Rebalancer.class.getName());
    // Even assignment: round-robin partitions across live consumers
    Map<String, List<Integer>> assign(List<String> consumers, int partitions) {
        Map<String, List<Integer>> map = new LinkedHashMap<>();
        for (String c : consumers) map.put(c, new ArrayList<>());
        if (consumers.isEmpty()) return map;
        for (int p = 0; p < partitions; p++) map.get(consumers.get(p % consumers.size())).add(p);
        return map;
    }
    // On revoke, commit offset so the new owner resumes correctly
    void commitOnRevoke(PartitionLog partition) {
        log.info(() -> "REVOKE partition " + partition.getId()
                + " commit offset=" + partition.getCommittedOffset());
    }
}

