class ProcessorGroup {
    private static final Logger log = Logger.getLogger(ProcessorGroup.class.getName());
    private final String groupId;
    private final int partitions;
    private final List<String> consumers = new ArrayList<>();
    private final Rebalancer rebalancer = new Rebalancer();
    private final List<PartitionLog> logs = new ArrayList<>();
    ProcessorGroup(String groupId, int partitions) {
        this.groupId = groupId; this.partitions = partitions;
        for (int i = 0; i < partitions; i++) {
            PartitionLog pl = new PartitionLog(i);
            pl.commit(100 + i); // pretend each partition processed up to some offset
            logs.add(pl);
        }
    }
    void join(String id) {
        // Before reassigning, revoke-commit each partition (clean handover)
        logs.forEach(rebalancer::commitOnRevoke);
        consumers.add(id);
        log.info(() -> "[" + groupId + "] " + id + " joined — REBALANCE");
    }
    void fail(String id) {
        logs.forEach(rebalancer::commitOnRevoke);
        consumers.remove(id);
        log.info(() -> "[" + groupId + "] " + id + " removed — REBALANCE");
    }
    void showLoad() {
        Map<String, List<Integer>> a = rebalancer.assign(consumers, partitions);
        a.forEach((c, parts) ->
            log.info(() -> "[" + groupId + "] " + c + " owns " + parts.size()
                    + " partitions " + parts));
    }
}

